// src/components/Sidebar/index.tsx

"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import Image from "next/image";
import { toast } from "sonner"; // Import sonner
import { clearAuth } from "@/utils/auth"; // Import your existing auth util
import { MENU_ITEMS, BOTTOM_MENU_ITEMS, LOGOUT_ITEM } from "@/constants/SidebarMenuItems";
import cn from "@/lib/utils";

export default function Sidebar({ className }: { className?: string }) {
	const pathname = usePathname();
	const router = useRouter();

	// Temporary Logout Logic
	const handleLogout = () => {
		// 1. Clear local storage token (using your existing util)
		clearAuth();

		// 2. Show Success Toast
		toast.success("Logged out successfully");

		// 3. Redirect to root/login page
		router.push("/");
	};

	const NavItem = ({ item, isLogout = false }: { item: any; isLogout?: boolean }) => {
		const isActive =
			pathname === item.href ||
			(pathname.startsWith(item.href) && item.href !== "/dashboard");

		// Shared styles for both Link and Button
		const commonClasses = cn(
			"flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors w-full text-left", // Added w-full and text-left for button alignment

			"text-muted-foreground hover:bg-muted hover:text-foreground",

			isActive && !isLogout && "bg-muted text-primary",

			isLogout && "text-destructive hover:bg-destructive/10 hover:text-destructive mt-4",

			className,
		);

		// If it's the logout item, render a Button with onClick handler
		if (isLogout) {
			return (
				<button onClick={handleLogout} className={commonClasses}>
					<item.icon className={cn("h-5 w-5", "text-destructive")} />
					<span>{item.label}</span>
				</button>
			);
		}

		// Otherwise, render a standard Next.js Link
		return (
			<Link href={item.href} className={commonClasses}>
				<item.icon
					className={cn("h-5 w-5", isActive ? "text-primary" : "text-currentColor")}
				/>
				<span>{item.label}</span>
			</Link>
		);
	};

	return (
		<aside
			className={cn(
				"hidden lg:flex flex-col w-[280px] bg-background h-screen fixed left-0 top-0 border-r border-border",
				className,
			)}
		>
			<div className="border-border flex h-20 items-center border-b px-6">
				<div className="relative size-24">
					<Link href="/dashboard">
						<Image
							src="/assets/logo_gohive_dark.png"
							alt="GoHive"
							fill
							className="object-contain object-left"
							priority
						/>
					</Link>
				</div>
			</div>

			<div className="scrollbar-none flex-1 space-y-1 overflow-y-auto px-4 py-6">
				{MENU_ITEMS.map((item) => (
					<NavItem key={item.href} item={item} />
				))}

				<div className="border-border mt-6 border-t pt-6">
					<p className="text-muted-foreground mb-2 px-4 text-xs font-semibold uppercase tracking-wider">
						Other
					</p>
					{BOTTOM_MENU_ITEMS.map((item) => (
						<NavItem key={item.href} item={item} />
					))}

					{/* Logout Item */}
					<NavItem item={LOGOUT_ITEM} isLogout />
				</div>
			</div>
		</aside>
	);
}

"use client";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Icon } from "@iconify/react";
import { useState } from "react";
import StepProgressBar from "../Shared/StepProgressBar";

export default function OwnershipVerification({
	onNext,
	onPrev,
	step = 2,
	totalSteps = 6,
}: {
	onNext?: () => void;
	onPrev?: () => void;
	step?: number;
	totalSteps?: number;
}) {
	const [fileName, setFileName] = useState("");

	return (
		<div className="w-full">
			<button
				onClick={onPrev}
				className="absolute right-0 top-0 flex size-8 items-center justify-center rounded-full bg-blue-50 text-blue-500 transition-colors hover:bg-blue-100"
			>
				<Icon icon="lucide:arrow-left" className="size-5" />
			</button>

			<StepProgressBar
				currentStep={step}
				totalSteps={totalSteps}
				title="Ownership Verification"
			/>

			<div className="space-y-6">
				<div className="relative space-y-2">
					<Label className="text-sm font-semibold text-gray-700">
						Government-issued ID Upload
					</Label>
					<p className="mb-2 text-xs text-gray-500">
						Upload Document (Passport / National ID / Driver's License)
					</p>

					<div className="relative flex items-center">
						<input
							type="text"
							value={fileName}
							placeholder="Upload"
							readOnly
							className="flex h-12 w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 pr-24 text-sm placeholder:text-gray-400 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-blue-500 disabled:cursor-not-allowed disabled:opacity-50"
						/>
						<label className="absolute right-2 top-1/2 -translate-y-1/2 cursor-pointer">
							<span className="rounded-full bg-green-600 px-4 py-1.5 text-xs font-semibold text-white transition-colors hover:bg-green-700">
								UPLOAD
							</span>
							<input
								type="file"
								className="hidden"
								onChange={(e) => setFileName(e.target.files?.[0]?.name || "")}
								accept=".png,.jpeg,.jpg,.pdf"
							/>
						</label>
					</div>
				</div>

				<Button
					onClick={onNext}
					className="text-md mt-8 h-12 w-full bg-yellow-500 font-sans font-semibold text-white hover:bg-yellow-600"
				>
					Next
				</Button>
			</div>
		</div>
	);
}

import { Button } from "@/components/ui/button";
import { Icon } from "@iconify/react";
import { Input } from "@/components/ui/input";

export default function OTPVerification({
	onNext,
	onPrev,
}: {
	onNext: () => void;
	onPrev: () => void;
}) {
	return (
		<div className="flex w-full flex-col items-center justify-center">
			<div className="mb-8 text-center">
				<h2 className="text-darkBlue-900 mb-2 text-2xl font-bold">Enter OTP Code</h2>
				<p className="px-8 text-sm text-gray-500">
					Enter the 6-digit code sent to your registered email (g***@company.com)
				</p>
			</div>

			<form
				className="w-full max-w-sm"
				onSubmit={(e) => {
					e.preventDefault();
					onNext();
				}}
			>
				{/* OTP Input UI Example - Usually we would use Shadcn OTP Input here, mocking standard spacing */}
				<div className="relative mb-6 w-full">
					<Input
						type="text"
						placeholder="X X X O O X"
						className="h-14 border-2 border-gray-200 bg-white text-center text-lg font-bold uppercase tracking-[1em] focus-visible:ring-blue-500"
						maxLength={6}
					/>
				</div>

				<div className="mb-8 text-center">
					<p className="text-sm text-gray-500">
						Didn't receive a code?{" "}
						<button type="button" className="font-medium text-blue-500 hover:underline">
							Resend OTP Code (15)
						</button>
					</p>
				</div>

				<Button
					type="submit"
					className="text-md mb-4 h-12 w-full bg-blue-500 font-sans font-semibold text-white hover:bg-blue-600"
				>
					Verify
				</Button>

				<button
					type="button"
					onClick={onPrev}
					className="hover:text-darkBlue-900 w-full text-center text-sm font-semibold text-gray-500 transition-colors"
				>
					Back
				</button>
			</form>
		</div>
	);
}

